const t={preflight:{intro:{t:0,b:{t:2,i:[{t:3}],s:"Швидка перевірка лише для читання, чи готовий принтер розпочати друк."}},refresh:{t:0,b:{t:2,i:[{t:3}],s:"Перевірити знову"}},checking:{t:0,b:{t:2,i:[{t:3}],s:"Перевірка…"}},ready:{t:0,b:{t:2,i:[{t:3}],s:"Готовий до друку"}},notReady:{t:0,b:{t:2,i:[{t:3}],s:"Не готовий до друку"}},checks:{unreachable:{fail:{t:0,b:{t:2,i:[{t:3}],s:"Принтер недоступний"}}},klippy:{pass:{t:0,b:{t:2,i:[{t:3}],s:"Klipper готовий"}},fail:{t:0,b:{t:2,i:[{t:3,v:"Klipper не готовий (стан: "},{t:4,k:"state"},{t:3,v:")"}]}}},idle:{pass:{t:0,b:{t:2,i:[{t:3}],s:"Друк не виконується"}},fail:{t:0,b:{t:2,i:[{t:3,v:"Друк уже виконується ("},{t:4,k:"state"},{t:3,v:")"}]}}},homed:{pass:{t:0,b:{t:2,i:[{t:3}],s:"Усі осі заздалегідь спарковані"}},fail:{t:0,b:{t:2,i:[{t:3,v:"Осі не спарковані ("},{t:4,k:"axes"},{t:3,v:"); запуск друку зазвичай спочатку виконує хоумінг"}]}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"Довідка"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"Довідка з перевірки перед друком"}},close:{t:0,b:{t:2,i:[{t:3}],s:"Закрити"}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:"Що таке перевірка перед друком?"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Погляд лише для читання на те, чи готовий принтер до запуску: він нічого не переміщує й не змінює, а лише звітує. Жорсткі блокувальники роблять вердикт червоним; попередження інформують, але не блокують."}}},checks:{title:{t:0,b:{t:2,i:[{t:3}],s:"Що перевіряється"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Чи готовий Klipper (не вимкнено й не в стані помилки), чи не виконується вже друк, та чи спарковані осі (інформативно, оскільки запуск друку зазвичай спочатку виконує хоумінг)."}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"Глосарій"}}}},glossary:{klippyState:{term:{t:0,b:{t:2,i:[{t:3}],s:"Стан Klipper"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Власний статус Klipper - 'ready' означає, що він підключений і простоює; 'shutdown' або 'error' означає, що він не може друкувати, доки стан не буде скинуто."}}},homing:{term:{t:0,b:{t:2,i:[{t:3}],s:"Хоумінг"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Переміщення кожної осі до її кінцевого вимикача (endstop), щоб принтер знав, де перебуває друкувальна головка (toolhead). Більшість процедур запуску друку виконують хоумінг автоматично."}}}}}}};export{t as default};
